import json

# 生成双端同构海阔规则 rule.json

find_rule = """js:
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
var channel = 20;
var page = 1;

var cateMap = {
    '日漫': 20, '20': 20,
    '国漫': 21, '21': 21,
    '剧场': 22, '22': 22,
    '美漫': 23, '23': 23,
    '特摄': 25, '25': 25,
    '少儿': 32, '32': 32,
    '动态漫': 26, '26': 26,
    '猜你想看': 27, '27': 27
};

if (typeof MY_CATE !== 'undefined' && MY_CATE) {
    var rawCate = String(MY_CATE).trim();
    if (cateMap[rawCate]) {
        channel = cateMap[rawCate];
    } else if (parseInt(rawCate)) {
        channel = parseInt(rawCate);
    }
}

var u = (typeof MY_URL !== 'undefined' && MY_URL) ? String(MY_URL) : (typeof input !== 'undefined' ? String(input) : '');
if (u) {
    var matchQuery = u.match(/(?:channel|cid|cate|class)=(\\d+)/i);
    if (matchQuery) {
        channel = parseInt(matchQuery[1]) || channel;
    } else {
        var hashParts = u.split('#');
        if (hashParts.length > 1 && hashParts[1]) {
            var rawHash1 = hashParts[1].trim();
            if (cateMap[rawHash1]) {
                channel = cateMap[rawHash1];
            } else if (/^\\d+$/.test(rawHash1)) {
                channel = parseInt(rawHash1) || channel;
            }
        }
        if (hashParts.length > 2 && hashParts[2]) {
            var rawHash2 = hashParts[2].trim();
            if (/^\\d+$/.test(rawHash2)) {
                if (typeof MY_PAGE === 'undefined' || !MY_PAGE) {
                    page = parseInt(rawHash2) || page;
                }
            }
        }
    }
    for (var k in cateMap) {
        if (cateMap.hasOwnProperty(k) && isNaN(k) && u.indexOf(k) !== -1) {
            channel = cateMap[k];
            break;
        }
    }
}

if (typeof MY_PAGE !== 'undefined' && MY_PAGE) {
    page = parseInt(MY_PAGE) || page;
}

var res = request(base + '/call', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
        command: 'catalog.get_video_list',
        payload: { channel: channel, page: page }
    })
});

var parsed = JSON.parse(res);
if (!parsed.ok) {
    throw new Error(parsed.error ? parsed.error.message : 'Bridge call failed');
}

var items = (parsed.data && parsed.data.items) ? parsed.data.items : [];
var d = [];
for (var i = 0; i < items.length; i++) {
    var it = items[i];
    d.push({
        title: it.name,
        desc: it.continu || (it.year ? it.year + '年' : ''),
        pic_url: it.pic,
        url: String(it.id),
        col_type: 'movie_3'
    });
}
setResult(d);
"""

search_rule = """js:
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
var keyword = '';

if (typeof KEYWORD !== 'undefined' && KEYWORD) {
    keyword = KEYWORD;
} else if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) {
    keyword = MY_KEYWORD;
} else if (typeof KEY !== 'undefined' && KEY) {
    keyword = KEY;
}

if (!keyword && typeof input !== 'undefined' && input) {
    var m = String(input).match(/key=([^&]+)/);
    if (m) {
        keyword = decodeURIComponent(m[1]);
    } else {
        keyword = String(input);
    }
}

if (!keyword && typeof MY_URL !== 'undefined' && MY_URL) {
    var m2 = String(MY_URL).match(/key=([^&]+)/);
    if (m2) {
        keyword = decodeURIComponent(m2[1]);
    }
}

var page = '1';
if (typeof MY_PAGE !== 'undefined' && MY_PAGE) {
    page = String(MY_PAGE);
}

var res = request(base + '/call', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
        command: 'catalog.search_video',
        payload: { key: keyword, page: page }
    })
});

var parsed = JSON.parse(res);
if (!parsed.ok) {
    throw new Error(parsed.error ? parsed.error.message : 'Bridge search failed');
}

var items = (parsed.data && parsed.data.items) ? parsed.data.items : [];
var d = [];
for (var i = 0; i < items.length; i++) {
    var it = items[i];
    d.push({
        title: it.name,
        desc: it.continu || (it.year ? it.year + '年' : ''),
        pic_url: it.pic,
        url: String(it.id),
        col_type: 'movie_3'
    });
}
setResult(d);
"""

detail_find_rule = """js:
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var videoId = String(currentUrl).split('@')[0].trim();

var res = request(base + '/call', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
        command: 'catalog.get_video_detail',
        payload: { id: videoId }
    })
});

var parsed = JSON.parse(res);
if (!parsed.ok) {
    throw new Error(parsed.error ? parsed.error.message : 'Bridge detail failed');
}

var detail = parsed.data || {};
var d = [];

// 铁律 5: 首卡必须为 pic_1_card 并显式注入剧名契约
var cleanTitle = detail.name || '动漫共和国';
d.push({
    title: '剧名：' + cleanTitle,
    desc: (detail.continu ? '更新至：' + detail.continu + '\\n' : '') +
          (detail.type ? '类型：' + detail.type + '\\n' : '') +
          (detail.content ? detail.content : ''),
    pic_url: detail.pic,
    url: currentUrl,
    col_type: 'pic_1_card'
});

var parts = detail.parts || [];
for (var p = 0; p < parts.length; p++) {
    var group = parts[p];
    var lineName = group.play_zh || ('线路 ' + (p + 1));
    var playLine = group.play || 'cn';
    d.push({
        title: '【' + lineName + '】',
        col_type: 'text_1'
    });
    var epList = group.part || [];
    for (var e = 0; e < epList.length; e++) {
        var epName = epList[e];
        var itemPayload = encodeURIComponent(JSON.stringify({
            id: videoId,
            part: epName,
            play: playLine
        }));

