            'for (var k in hdrs) { if (hdrs.hasOwnProperty(k)) { hp.push(k + "@" + hdrs[k]); } }' +
            'if (hp.length > 0) { purl = purl + ";{" + hp.join("&&") + "}"; }' +
            'return purl;' +
        '})()';

        d.push({
            title: epName,
            url: itemPayload + lazyScript,
            col_type: 'text_3'
        });
    }
